window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-33501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύβουλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3183 na letra π · nº geral 33501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito prudente; muito sábio. 〈πολύς, βουλή〉</p></section></article>\n<article id=\"entry-dgp-33502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυβούτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 3184 na letra π · nº geral 33502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) rico de bois; que tem rebanho bovino. 〈πολύς, βοῦς〉</p></section></article>\n<article id=\"entry-dgp-33503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύγελως, ωτος</h1><div class=\"entry-meta\"><span>DGP · ordem 3185 na letra π · nº geral 33503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) amante dos jogos e dos risos. 〈πολύς, γέλως〉</p></section></article>\n<article id=\"entry-dgp-33504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυγηθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3186 na letra π · nº geral 33504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de alegria; feliz 2 que causa alegria. 〈πολύς, γηθέω〉</p></section></article>\n<article id=\"entry-dgp-33505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύγλωσσος,</h1><div class=\"entry-meta\"><span>DGP · ordem 3187 na letra π · nº geral 33505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. πολύγλωττος, ος, ον 1 de muitas línguas, falas ou vozes; que emite muitos oráculos 2 loquaz 3 de gritos incessantes 4 que fala muitas línguas; poliglota. 〈πολύς, γλῶσσα〉</p></section></article>\n<article id=\"entry-dgp-33506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύγομφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3188 na letra π · nº geral 33506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guarnecido de numerosos pregos; solidamente construído. 〈πολύς, γόμφος〉</p></section></article>\n<article id=\"entry-dgp-33507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυγονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3189 na letra π · nº geral 33507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 produzir muito; ser fértil ♦ pas. 2 propagar-se. 〈πολύγονος〉</p></section></article>\n<article id=\"entry-dgp-33508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύγονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3190 na letra π · nº geral 33508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito fecundο; prolífico 2 fertilizante; fecundador. 〈πολύς, γίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-33509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυγράμματος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3191 na letra π · nº geral 33509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de muitas letras; constituído de muitas letras 2 muito letrado; muito culto. 〈πολύς, γράμμα〉</p></section></article>\n<article id=\"entry-dgp-33510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυγύμναστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3192 na letra π · nº geral 33510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito exercitado ou hábil em muitas coisas. 〈πολύς, γυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-33511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύγωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3193 na letra π · nº geral 33511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem vários ângulos; polígono. 〈πολύς, γωνία〉</p></section></article>\n<article id=\"entry-dgp-33512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδαίδαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3194 na letra π · nº geral 33512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalhado com muita arte; ricamente trabalhado 2 que trabalha com muita arte; engenhoso. 〈πολύς, δαίδαλος〉</p></section></article>\n<article id=\"entry-dgp-33513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδάκρυος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3195 na letra π · nº geral 33513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que faz verter lágrimas abundantes.</p></section></article>\n<article id=\"entry-dgp-33514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύδακρυς, υος</h1><div class=\"entry-meta\"><span>DGP · ordem 3196 na letra π · nº geral 33514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que faz verter ou que provoca lágrimas abundantes; funesto (guerra) 2 acompanhado de lágrimas abundantes (grito, gemido) 3 que verte muitas lágrimas. 〈πολύς, δάκρυ〉</p></section></article>\n<article id=\"entry-dgp-33515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδάκρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3197 na letra π · nº geral 33515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πολύδακρυς.</p></section></article>\n<article id=\"entry-dgp-33516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδάπανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3198 na letra π · nº geral 33516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gasta muito; pródigo 2 que causa muitas despesas; custoso 〈πολύς, δαπάνη〉</p></section></article>\n<article id=\"entry-dgp-33517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδειράς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 3199 na letra π · nº geral 33517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de muitos cumes, epít. do Olim­po. 〈πολύς, δειράς〉</p></section></article>\n<article id=\"entry-dgp-33518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδένδρεος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3200 na letra π · nº geral 33518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de árvores; arborizado. 〈πο­λύς, δένδρον〉</p></section></article>\n<article id=\"entry-dgp-33519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύδεσμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3201 na letra π · nº geral 33519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito ligado; bem atado. 〈πολύς, δέσμος〉</p></section></article>\n<article id=\"entry-dgp-33520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πολυδεύκης, εος-ους (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3202 na letra π · nº geral 33520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Polideuces ou Pólux, filho de Zeus e de Leda, irmão de Castor.</p></section></article>\n<article id=\"entry-dgp-33521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πολυδεύκιον ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3203 na letra π · nº geral 33521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de Πολυδεύκης.</p></section></article>\n<article id=\"entry-dgp-33522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδίψιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3204 na letra π · nº geral 33522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito ressecado; árido 2 de que se tem muita sede; muito desejado. 〈πολύς, δίψα〉</p></section></article>\n<article id=\"entry-dgp-33523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύδονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3205 na letra π · nº geral 33523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se agita muito; muito agitado. 〈πολύς, δονέω〉</p></section></article>\n<article id=\"entry-dgp-33524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύδρομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3206 na letra π · nº geral 33524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que corre de todos os lados; que corre muito; que corre longe. 〈πολύς, δραμεῖν〉</p></section></article>\n<article id=\"entry-dgp-33525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυδωρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3207 na letra π · nº geral 33525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grande liberalidade; generosidade. 〈πολύδωρος〉</p></section></article>\n<article id=\"entry-dgp-33526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύδωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3208 na letra π · nº geral 33526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que recebeu grandes presentes ou um rico dote. 〈πολύς, δῶρον〉</p></section></article>\n<article id=\"entry-dgp-33527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύεδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3209 na letra π · nº geral 33527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muitos assentos; com muitos graus. 〈πολύς, ἕδρας〉</p></section></article>\n<article id=\"entry-dgp-33528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3210 na letra π · nº geral 33528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de diferentes tipos; de várias formas ou espécies; variado. 〈πολύς, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-33529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυεπαίνετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3211 na letra π · nº geral 33529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito louvado; muito enaltecido. 〈πολύς, ἐπαινέω〉</p></section></article>\n<article id=\"entry-dgp-33530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3212 na letra π · nº geral 33530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muitas palavras; que fala muito. 〈πολύς, ἔπος〉</p></section></article>\n<article id=\"entry-dgp-33531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυέραστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3213 na letra π · nº geral 33531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito amado. 〈πολύς, ἐράω〉</p></section></article>\n<article id=\"entry-dgp-33532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύευκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3214 na letra π · nº geral 33532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito invocado ou desejado 2 desejado por muito tempo. 〈πολύς, εὔχομαι〉</p></section></article>\n<article id=\"entry-dgp-33533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πολυζήλειος αὐλή (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3215 na letra π · nº geral 33533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pátio de Polizelo, local próximo a Siracusa.</p></section></article>\n<article id=\"entry-dgp-33534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύζηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3216 na letra π · nº geral 33534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito desejado, amado, apreciado 2 muito invejado. 〈πολύς, ζῆλος〉</p></section></article>\n<article id=\"entry-dgp-33535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυζήλωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3217 na letra π · nº geral 33535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que é objeto de um culto devotado; reverenciado; venerado. 〈πολύς, ζηλόω〉</p></section></article>\n<article id=\"entry-dgp-33536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύζυγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3218 na letra π · nº geral 33536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem muitos bancos de remadores. 〈πολύς, ζυγόν〉</p></section></article>\n<article id=\"entry-dgp-33537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυηγερής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3219 na letra π · nº geral 33537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">reunido em massa. 〈πολύς, ἀγείρω〉</p></section></article>\n<article id=\"entry-dgp-33538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυήμερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3220 na letra π · nº geral 33538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muitos dias; que dura muitos dias. 〈πολύς, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-33539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυήρατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3221 na letra π · nº geral 33539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito amado; muito desejado; caro 2 amável; charmoso; desejável. 〈πολύς, ἔραμαι〉</p></section></article>\n<article id=\"entry-dgp-33540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυηχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3222 na letra π · nº geral 33540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de sons variados 2 muito sonoro; ressoante. 〈πολύς, ἦχος〉</p></section></article>\n<article id=\"entry-dgp-33541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυήχητος,</h1><div class=\"entry-meta\"><span>DGP · ordem 3223 na letra π · nº geral 33541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. πολυάχετος, ος, ον muito sonoro; ressoante. 〈πολύς, ἠχέω〉</p></section></article>\n<article id=\"entry-dgp-33542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυήχως</h1><div class=\"entry-meta\"><span>DGP · ordem 3224 na letra π · nº geral 33542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com várias vozes; com voz ressoante.</p></section></article>\n<article id=\"entry-dgp-33543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυθαρσής, ής, έν</h1><div class=\"entry-meta\"><span>DGP · ordem 3225 na letra π · nº geral 33543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de coragem ou de ardor; pleno de confiança; audacioso. 〈πολύς, θάρσος〉</p></section></article>\n<article id=\"entry-dgp-33544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύθεος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3226 na letra π · nº geral 33544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de muitos deuses; comum a muitos deuses; que compreende muitos deuses 2 que adora muitos deuses; politeísta. 〈πολύς, θεός〉</p></section></article>\n<article id=\"entry-dgp-33545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύθερμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3227 na letra π · nº geral 33545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito quente. 〈πολύς, θερμός〉</p></section></article>\n<article id=\"entry-dgp-33546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύθηρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3228 na letra π · nº geral 33546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 com muitas feras; abundante de animais selvagens 2 com muitos peixes; com abundância de pesca. 〈πολύς, θήρα〉</p></section></article>\n<article id=\"entry-dgp-33547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυθρέμμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3229 na letra π · nº geral 33547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 que nutre muito ou a muitos; nutriz 2 fecundador. 〈πολύς, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-33548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύθρηνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3230 na letra π · nº geral 33548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de muitos lamentos; muito lastimoso (canto) 2 que se lamenta muito; queixoso 3 triste. 〈πολύς, θρῆνος〉</p></section></article>\n<article id=\"entry-dgp-33549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύθροος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 3231 na letra π · nº geral 33549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muitas vozes; muito barulhento; muito sonoro. 〈πολύς, θρόος〉</p></section></article>\n<article id=\"entry-dgp-33550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυθρύλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3232 na letra π · nº geral 33550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">objeto de muito discurso ou discussão; de quem ou de que se fala muito; famoso; célebre. 〈πολύς, θρυλέω〉</p></section></article>\n<article id=\"entry-dgp-33551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύθυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3233 na letra π · nº geral 33551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de numerosas portas ou janelas; com muitas aberturas 2 cheio de buracos 3 de numerosas folhas; volumoso. 〈πολύς, θύρα〉</p></section></article>\n<article id=\"entry-dgp-33552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύθυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3234 na letra π · nº geral 33552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acompanhado de ou que se compõe de numerosos sacrifícios 2 local onde se oferecem numerosos sacrifícios. 〈πολύς, θύω〉</p></section></article>\n<article id=\"entry-dgp-33553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυϊδρεία,</h1><div class=\"entry-meta\"><span>DGP · ordem 3235 na letra π · nº geral 33553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. πολυϊδρείη, ης (ἡ) grande ciência; sabedoria; prudência; habilidade. 〈πολύϊδρις〉</p></section></article>\n<article id=\"entry-dgp-33554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύϊδρις, ιος</h1><div class=\"entry-meta\"><span>DGP · ordem 3236 na letra π · nº geral 33554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. εως (masc., fem.) que sabe muito; sábio; prudente; hábil. 〈πολύς, εἴδω〉</p></section></article>\n<article id=\"entry-dgp-33555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύϊππος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3237 na letra π · nº geral 33555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem muitos cavalos. 〈πολύς, ἵππος〉</p></section></article>\n<article id=\"entry-dgp-33556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκαγκής, ής, έν</h1><div class=\"entry-meta\"><span>DGP · ordem 3238 na letra π · nº geral 33556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que seca totalmente; que queima; ardente 2 muito seco; árido.</p></section></article>\n<article id=\"entry-dgp-33557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκαισαρίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3239 na letra π · nº geral 33557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">governo de muitos Césares ou de muitos imperadores ao mesmo tempo. 〈πολύς, Καῖσαρ〉</p></section></article>\n<article id=\"entry-dgp-33558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκαμπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3240 na letra π · nº geral 33558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com muitas curvas; muito sinuoso. 〈πολύς, κάμπτω〉</p></section></article>\n<article id=\"entry-dgp-33559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3241 na letra π · nº geral 33559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muitas vítimas (sacrifício). 〈πολύς, καίνω〉</p></section></article>\n<article id=\"entry-dgp-33560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκαρπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3242 na letra π · nº geral 33560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abundância de frutos. 〈πολύκαρπος〉</p></section></article>\n<article id=\"entry-dgp-33561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκαρπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3243 na letra π · nº geral 33561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que produz muitos frutos; muito fecundo; fértil 2 com muitas frutas; rico de frutas. 〈πολύς, καρπός〉</p></section></article>\n<article id=\"entry-dgp-33562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκέλαδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3244 na letra π · nº geral 33562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muitos cantos; muito barulhento; ressoante.</p></section></article>\n<article id=\"entry-dgp-33563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκερδείη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3245 na letra π · nº geral 33563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. trapaça; astúcia; esperteza. 〈πολυκερδής〉</p></section></article>\n<article id=\"entry-dgp-33564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκερδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3246 na letra π · nº geral 33564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito hábil para ganhar; que busca o ganho 2 muito esperto; perspicaz; trapaceiro. 〈πολύς, κέρδος〉</p></section></article>\n<article id=\"entry-dgp-33565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκερως, ως, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3247 na letra π · nº geral 33565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ω, dat. ῳ, gen. ων 1 de muitos chifres 2 de muitos animais de cornos. 〈πολύς, κέρας〉</p></section></article>\n<article id=\"entry-dgp-33566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκεστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3248 na letra π · nº geral 33566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ornado de bordados ou de desenhos variados.</p></section></article>\n<article id=\"entry-dgp-33567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκέφαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3249 na letra π · nº geral 33567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem muitas cabeças: πολυκέ­φαλος νόμος plut. tipo de ritmo para reproduzir na flauta o silvo das serpentes da cabeça da Górgona. 〈πολύς, κεφαλή〉</p></section></article>\n<article id=\"entry-dgp-33568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκηδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3250 na letra π · nº geral 33568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que causa grande aflição; penoso (retorno) 2 cuidadoso; zeloso (pessoa). 〈πολύς, κῆδος〉</p></section></article>\n<article id=\"entry-dgp-33569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκίνητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3251 na letra π · nº geral 33569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dotado de muito movimento ou muitos movimentos; muito móvel 2 fortemente agitado ou que se agita muito. 〈πολύς, κινέω〉</p></section></article>\n<article id=\"entry-dgp-33570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκλαγγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3252 na letra π · nº geral 33570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só superl. πολυκλαγγότατος de numerosos ou variados gritos. 〈πολύς, κλαγγή〉</p></section></article>\n<article id=\"entry-dgp-33571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκλαυστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3253 na letra π · nº geral 33571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πολύκλαυτος.</p></section></article>\n<article id=\"entry-dgp-33572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκλαυτος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 3254 na letra π · nº geral 33572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 que é objeto de muito pranto; que causa muita lamentação; muito chorado 2 que é causa de pranto. 〈πολύς, κλαίω〉</p></section></article>\n<article id=\"entry-dgp-33573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκλήϊς, ϊδος</h1><div class=\"entry-meta\"><span>DGP · ordem 3255 na letra π · nº geral 33573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de muitos bancos para os remadores (navio). 〈πολύς, κληΐς〉</p></section></article>\n<article id=\"entry-dgp-33574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκληρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3256 na letra π · nº geral 33574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que recebeu numerosas heranças; muito rico. 〈πολύς, κλῆρος〉</p></section></article>\n<article id=\"entry-dgp-33575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3257 na letra π · nº geral 33575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chamado de muitos lugares, de muitas partes (aliados troianos). 〈πολύς, καλέω〉</p></section></article>\n<article id=\"entry-dgp-33576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκλυστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3258 na letra π · nº geral 33576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de ondas fortemente agitadas (mar). 〈πολύς, κλύζω〉</p></section></article>\n<article id=\"entry-dgp-33577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκμητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3259 na letra π · nº geral 33577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que requer muita fadiga; que custa muito trabalho ou dor; feito a duras penas 2 resistente à fadiga. 〈πολύς, κάμνω〉</p></section></article>\n<article id=\"entry-dgp-33578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκνημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3260 na letra π · nº geral 33578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito montanhoso. 〈πολύς, κνήμη〉</p></section></article>\n<article id=\"entry-dgp-33579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκοινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3261 na letra π · nº geral 33579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 comum a muitos ou a todos 2 promíscuo. 〈πολύς, κοινός〉</p></section></article>\n<article id=\"entry-dgp-33580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκοιρανία,</h1><div class=\"entry-meta\"><span>DGP · ordem 3262 na letra π · nº geral 33580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. -ίη, ης (ἡ) governo de muitos. 〈πο­λύς, κοίρανος〉</p></section></article>\n<article id=\"entry-dgp-33581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκρατής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3263 na letra π · nº geral 33581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito poderoso; todo-poderoso. 〈πολύς, κράτος〉</p></section></article>\n<article id=\"entry-dgp-33582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκτήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3264 na letra π · nº geral 33582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que possui muito; muito rico; opulento. 〈πολύς, κτῆμα〉</p></section></article>\n<article id=\"entry-dgp-33583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκτητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3265 na letra π · nº geral 33583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πολυκτήμων.</p></section></article>\n<article id=\"entry-dgp-33584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυκτόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3266 na letra π · nº geral 33584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que causa a morte de muitos; que mata muitos; exterminador.</p></section></article>\n<article id=\"entry-dgp-33585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύκωπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3267 na letra π · nº geral 33585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de numerosos remos. 〈πολύς, κώπη〉</p></section></article>\n<article id=\"entry-dgp-33586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυλήϊος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3268 na letra π · nº geral 33586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rico em campos de trigo 2 rentável; opulento. 〈πολύς, λήϊον〉</p></section></article>\n<article id=\"entry-dgp-33587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύλαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3269 na letra π · nº geral 33587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tagarela; loquaz. 〈πολύς, λαλέω〉</p></section></article>\n<article id=\"entry-dgp-33588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύλιμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3270 na letra π · nº geral 33588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grande apetite; voracidade. 〈πολύς, λιμός〉</p></section></article>\n<article id=\"entry-dgp-33589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύλλιστος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 3271 na letra π · nº geral 33589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 invocado com muitas orações; muito suplicado 2 objeto de grande culto. 〈πολύς, λίσσομαι〉</p></section></article>\n<article id=\"entry-dgp-33590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυλογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3272 na letra π · nº geral 33590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abundância de palavras (no bom e no mau sentido). 〈πολυλόγος〉</p></section></article>\n<article id=\"entry-dgp-33591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυλόγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3273 na letra π · nº geral 33591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que fala muito; loquaz; verborrágico. 〈πολύς, λέγω〉</p></section></article>\n<article id=\"entry-dgp-33592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμάθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3274 na letra π · nº geral 33592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grande saber; polimatia. 〈πολυμαθής〉</p></section></article>\n<article id=\"entry-dgp-33593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 3275 na letra π · nº geral 33593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que sabe muito; muito sábio; culto. 〈πολύς, μανθάνω〉</p></section></article>\n<article id=\"entry-dgp-33594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμαθία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3276 na letra π · nº geral 33594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πολυμάθεια.</p></section></article>\n<article id=\"entry-dgp-33595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμάντευτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3277 na letra π · nº geral 33595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cujos oráculos são muito consultados. 〈πολύς, μαντεύομαι〉</p></section></article>\n<article id=\"entry-dgp-33596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμάχητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3278 na letra π · nº geral 33596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de muitos combates. 〈πολύς, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-33597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμέρεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3279 na letra π · nº geral 33597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grande número de partes; multiplicidade de partes. 〈πολύς, μέρος 〉</p></section></article>\n<article id=\"entry-dgp-33598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμερῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 3280 na letra π · nº geral 33598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em várias partes; de vários tipos; diversamente.</p></section></article>\n<article id=\"entry-dgp-33599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμηκάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 3281 na letra π · nº geral 33599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) que bale sem cessar. 〈πολύς, μηκάς〉</p></section></article>\n<article id=\"entry-dgp-33600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύμηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3282 na letra π · nº geral 33600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ricο em carneiros; rico em rebanhos. 〈πολύς, μῆλον〉</p></section></article>\n";
